// Arma el body de la request a Cohere para clasificar.
// Modelo chico: la tarea es estructurada y de bajo razonamiento.
const MODELO      = 'command-r7b-12-2024';   // alternativa: command-a-03-2025
const MAX_TOKENS  = 300;
const TEMPERATURA = 0.2;

const SYSTEM = "Sos el motor de triage de la mesa de ayuda de NimbusCRM, un SaaS de gestión de contactos.\nClasificá el ticket y generá ÚNICAMENTE un objeto JSON válido, sin markdown, sin backticks, sin texto adicional.\n\nEstructura exacta del JSON:\n{\n  \"categoria\": \"Facturación\" | \"Bug técnico\" | \"Cómo hacer\" | \"Solicitud de función\" | \"Fuera de alcance\",\n  \"prioridad\": \"P1\" | \"P2\" | \"P3\",\n  \"sentimiento\": \"Neutro\" | \"Frustrado\" | \"Enojado\",\n  \"resumen\": \"máximo 30 palabras, en español\",\n  \"confianza\": número entre 0 y 1\n}\n\nCriterios de prioridad:\nP1 = servicio caído, pérdida de datos o bloqueo total de trabajo\nP2 = funcionalidad degradada con workaround disponible\nP3 = consulta, duda o pedido de mejora\n\nUsá \"Fuera de alcance\" cuando el mensaje no sea una consulta de soporte del producto\n(spam, pedidos de empleo, consultas comerciales). En ese caso prioridad \"P3\".\n\nRespetá las tildes y las mayúsculas de los valores tal cual están escritos arriba.";

const n = $('SET · Normalizar Ticket').first().json;

// Minimización de datos: al modelo NO se le envía nombre, email ni empresa.
const user = [
  'Asunto: ' + n.asunto,
  'Descripción: ' + n.descripcion,
  'Plan del cliente: ' + n.plan,
].join('\n');

return [{ json: { body: {
  model: MODELO,
  temperature: TEMPERATURA,
  max_tokens: MAX_TOKENS,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user',   content: user },
  ],
}}}];

// Valida la respuesta del clasificador antes de escribirla en Airtable.
// Soporta la forma de respuesta de Cohere v2, OpenAI y Anthropic.
const CATEGORIAS   = ['Facturación', 'Bug técnico', 'Cómo hacer', 'Solicitud de función', 'Fuera de alcance'];
const PRIORIDADES  = ['P1', 'P2', 'P3'];
const SENTIMIENTOS = ['Neutro', 'Frustrado', 'Enojado'];

const salida = [];

for (const item of $input.all()) {
  let data = item.json?.message?.content ?? item.json?.content ?? item.json?.text ?? item.json;

  // Cohere v2 y Anthropic devuelven bloques de contenido en un array
  if (Array.isArray(data)) data = data.map(b => b?.text ?? '').join('');

  if (typeof data === 'string') {
    const limpio = data.replace(/```json/gi, '').replace(/```/g, '').trim();
    try { data = JSON.parse(limpio); }
    catch (e) { throw new Error('La IA no devolvió JSON válido: ' + limpio.slice(0, 200)); }
  }

  const faltantes = ['categoria', 'prioridad', 'sentimiento', 'resumen', 'confianza']
    .filter(k => data[k] === undefined || data[k] === null || data[k] === '');
  if (faltantes.length) throw new Error('Faltan campos en la respuesta de la IA: ' + faltantes.join(', '));

  if (!CATEGORIAS.includes(data.categoria))     throw new Error('Categoría no reconocida: ' + data.categoria);
  if (!PRIORIDADES.includes(data.prioridad))    throw new Error('Prioridad no reconocida: ' + data.prioridad);
  if (!SENTIMIENTOS.includes(data.sentimiento)) throw new Error('Sentimiento no reconocido: ' + data.sentimiento);

  const confianza = Number(data.confianza);
  if (Number.isNaN(confianza)) throw new Error('Confianza no numérica: ' + data.confianza);

  salida.push({ json: {
    categoria:        data.categoria,
    prioridad:        data.prioridad,
    sentimiento:      data.sentimiento,
    resumen:          String(data.resumen).slice(0, 300),
    confianza:        Math.min(1, Math.max(0, confianza)),
    ticket_record_id: $('AT · Crear Ticket').first().json.id,
    ticket_id:        $('AT · Crear Ticket').first().json.fields['Ticket ID'],
    run_id:           $('SET · Normalizar Ticket').first().json.run_id,
  }});
}
return salida;

// Junta los artículos de la KB en un bloque de texto y consolida todo en un único ítem.
const arts = [];
const ids  = [];

for (const item of $input.all()) {
  const f = item.json?.fields ?? item.json ?? {};
  if (!f['Título']) continue;            // el nodo puede emitir un ítem vacío
  ids.push(item.json.id);
  arts.push('[' + (arts.length + 1) + '] ' + f['Título'] + '\n' + f['Contenido']);
}

const clasif = $('CODE · Validar Clasificación').first().json;
const norm   = $('SET · Normalizar Ticket').first().json;

return [{ json: {
  ...clasif,
  plan:            norm.plan,
  asunto:          norm.asunto,
  descripcion:     norm.descripcion,
  recibido_en:     norm.recibido_en,
  articulos_kb:    arts.length ? arts.join('\n\n') : 'SIN ARTÍCULOS RELEVANTES',
  articulos_ids:   ids,
  articulos_count: arts.length,
}}];

// Arma el body de la request a Cohere para redactar la respuesta.
// Modelo grande: tiene que leer los artículos de la KB y sostener el tono.
const MODELO      = 'command-a-03-2025';   // alternativa económica: command-r-08-2024
const MAX_TOKENS  = 700;
const TEMPERATURA = 0.4;

const SYSTEM = "Sos un agente de soporte de NimbusCRM, un SaaS de gestión de contactos.\n\nReglas:\n- Máximo 200 palabras.\n- Tono profesional y cálido, tratamiento de \"usted\".\n- Basate ÚNICAMENTE en los artículos de la base de conocimiento provistos.\n- Si los artículos no cubren el caso, o si recibís \"SIN ARTÍCULOS RELEVANTES\", indicá que el caso se escala a un especialista. No inventes pasos, menús ni plazos.\n- No prometas fechas de resolución.\n- No incluyas asunto ni encabezado de email, solo el cuerpo del mensaje.\n- Abrí exactamente con \"Hola,\" sin nombre propio.\n- Cerrá con la firma: \"Equipo de Soporte · NimbusCRM\".\n- Devolvé solo el texto de la respuesta, sin comentarios ni explicaciones.";

const c = $('CODE · Armar Contexto KB').first().json;

// En el reintento (segunda pasada del bucle) se le pide otro enfoque.
const reintento = $runIndex > 0
  ? 'ATENCIÓN: el intento anterior fue rechazado por el revisor humano. Reescribí la respuesta con un enfoque distinto, más directo y concreto.\n\n'
  : '';

const user = reintento + [
  '--- DATOS DEL TICKET ---',
  'Ticket: ' + c.ticket_id,
  'Categoría: ' + c.categoria,
  'Prioridad: ' + c.prioridad,
  'Sentimiento detectado: ' + c.sentimiento,
  'Plan contratado: ' + c.plan,
  '',
  'Asunto: ' + c.asunto,
  '',
  'Consulta:',
  c.descripcion,
  '',
  '--- BASE DE CONOCIMIENTO (' + c.articulos_count + ' artículos) ---',
  c.articulos_kb,
].join('\n');

return [{ json: { body: {
  model: MODELO,
  temperature: TEMPERATURA,
  max_tokens: MAX_TOKENS,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user',   content: user },
  ],
}}}];

// Extrae el texto del modelo, toma el consumo real de tokens y calcula costo y latencia.
// TARIFAS EN USD POR MILLÓN DE TOKENS — verificar en cohere.com/pricing antes de entregar.
const PRECIO_IN_POR_M  = 2.50;
const PRECIO_OUT_POR_M = 10.00;
const CHARS_POR_TOKEN  = 4;   // solo se usa si la API no devuelve el consumo

const r = $input.first().json;

let borrador = r?.message?.content ?? r?.text ?? r?.completion ?? '';
if (Array.isArray(borrador)) borrador = borrador.map(b => b?.text ?? '').join('');
borrador = String(borrador).trim();
if (!borrador) throw new Error('El modelo devolvió una respuesta vacía');

const ctx  = $('CODE · Armar Contexto KB').first().json;
const norm = $('SET · Normalizar Ticket').first().json;

// Cohere v2 devuelve el consumo real; si falta, se estima por longitud.
const u = r?.usage ?? {};
const tokensIn  = u?.tokens?.input_tokens  ?? u?.billed_units?.input_tokens
                  ?? Math.round((ctx.articulos_kb.length + ctx.descripcion.length + 600) / CHARS_POR_TOKEN);
const tokensOut = u?.tokens?.output_tokens ?? u?.billed_units?.output_tokens
                  ?? Math.round(borrador.length / CHARS_POR_TOKEN);

const costo = (tokensIn / 1000000) * PRECIO_IN_POR_M + (tokensOut / 1000000) * PRECIO_OUT_POR_M;

return [{ json: {
  borrador,
  intento:          $runIndex + 1,
  ticket_record_id: ctx.ticket_record_id,
  ticket_id:        ctx.ticket_id,
  categoria:        ctx.categoria,
  prioridad:        ctx.prioridad,
  articulos_count:  ctx.articulos_count,
  articulos_ids:    ctx.articulos_ids,
  run_id:           norm.run_id,
  tokens_in:        tokensIn,
  tokens_out:       tokensOut,
  costo_usd:        Number(costo.toFixed(6)),
  latencia_ms:      Date.now() - new Date(norm.recibido_en).getTime(),
}}];

